// docs/demo/dashboard.js — the example dashboard (two views: tablet and phone) with INVENTED entities and names.
// The single source for: docs/demo/dashboard.html (screenshots, fake Home Assistant) and examples/dashboard-calm.yaml
// (generated by `node docs/demo/make-yaml.mjs`). Replace the invented entity ids with yours.
(function () {
  const D = window.CCU_DEMO, A = D.A, S = D.states;
  const temp = (v, name) => A(v, { unit_of_measurement: '°C', device_class: 'temperature', friendly_name: name });

  // ---- invented entities used here and not in the other demo scenes ----
  Object.assign(S, {
    'group.all_windows': A('on', { friendly_name: 'Windows', entity_id: ['binary_sensor.bedroom_window', 'binary_sensor.office_window'] }),
    'binary_sensor.office_window': A('off', { friendly_name: 'Office window', device_class: 'window' }),
    'group.external_doors': A('off', { friendly_name: 'External doors', entity_id: ['binary_sensor.front_door_contact'] }),
    'binary_sensor.front_door_contact': A('off', { friendly_name: 'Front door contact', device_class: 'door' }),
    'group.water_leak': A('off', { friendly_name: 'Water leak' }), 'group.smoke_alarm': A('off', { friendly_name: 'Smoke alarm' }),
    'switch.air_cleaner': A('on', { friendly_name: 'Air cleaner' }), 'switch.uv_sterilizer': A('off', { friendly_name: 'UV sterilizer' }),
    'sensor.dishwasher_remaining': A('42', { unit_of_measurement: 'min', friendly_name: 'Dishwasher' }),
    'sensor.outdoor_temperature': temp('18.4', 'Outdoor temperature'),
    'sensor.import_month': A('86.4', { unit_of_measurement: 'kWh', friendly_name: 'Import this month' }),
    'light.ground_hall': A('off', { friendly_name: 'Ground hall' }), 'light.office': A('on', { friendly_name: 'Office' }), 'light.ground_bath': A('off', { friendly_name: 'Ground bath' }),
    'light.master_bedroom': A('off', { friendly_name: 'Master bedroom' }), 'light.dressing': A('off', { friendly_name: 'Dressing' }), 'light.guest_room': A('on', { friendly_name: 'Guest room' }),
    'light.upper_hall': A('off', { friendly_name: 'Upper hall' }), 'light.upper_bath': A('off', { friendly_name: 'Upper bath' }),
    'switch.shed_lights': A('on', { friendly_name: 'Shed lights' }), 'switch.gate': A('off', { friendly_name: 'Gate' }),
    'sensor.kitchen_temperature': temp('22.1', 'Kitchen'), 'sensor.ground_hall_temperature': temp('21.4', 'Ground hall'), 'sensor.office_temperature': temp('23.0', 'Office'),
    'sensor.ground_bath_temperature': temp('22.6', 'Ground bath'), 'sensor.master_bedroom_temperature': temp('20.8', 'Master bedroom'), 'sensor.dressing_temperature': temp('20.5', 'Dressing'),
    'sensor.guest_room_temperature': temp('21.9', 'Guest room'), 'sensor.upper_hall_temperature': temp('21.2', 'Upper hall'), 'sensor.upper_bath_temperature': temp('22.3', 'Upper bath'),
    'sensor.pool_temperature': temp('27.5', 'Pool'), 'sensor.shed_temperature': temp('24.8', 'Shed'),
  });

  const BASE = '/dashboard-calm';
  const nav = (p) => BASE + '/' + p;

  // ---- cards ----
  const chipsStatus = (cols) => ({
    type: 'custom:ccu-chips-card', grid_options: { columns: cols },
    entities: [
      { entity: 'group.all_lights', name: 'Lights', icon: 'mdi:lightbulb', hide_off: true, secondary: { entity: 'sensor.lights_on' } },
      { entity: 'group.all_windows', icon: 'mdi:window-open', count: true, hide_off: true },
      { entity: 'group.external_doors', icon: 'mdi:door-open', count: true, hide_off: true },
      { entity: 'group.water_leak', icon: 'mdi:water-alert', hide_off: true, on_as: 'alert' },
      { entity: 'group.smoke_alarm', icon: 'mdi:fire-alert', hide_off: true, on_as: 'alert' },
    ],
    low_batteries: { threshold: 20, tap_action: { action: 'navigate', navigation_path: nav('batteries') } },
    deadlines: {
      alert_days: 3, tap_action: { action: 'navigate', navigation_path: nav('cars') },
      vehicles: [
        { name: 'Family car', documents: [
          { label: 'Insurance', entity: 'input_datetime.car_insurance', icon: 'mdi:shield-car' }, { label: 'Inspection', entity: 'input_datetime.car_inspection', icon: 'mdi:car-wrench' },
          { label: 'Road tax', entity: 'input_datetime.car_road_tax', icon: 'mdi:highway' }, { label: 'Service', entity: 'sensor.car_service_date', icon: 'mdi:car-cog' },
          { label: 'Oil', odometer: 'sensor.car_odometer', last_km: 'input_number.car_oil_km', interval_km: 10000, icon: 'mdi:oil' }] },
        { name: 'Van', documents: [
          { label: 'Insurance', entity: 'input_datetime.van_insurance', icon: 'mdi:shield-car' }, { label: 'Inspection', entity: 'input_datetime.van_inspection', icon: 'mdi:car-wrench' },
          { label: 'Road tax', entity: 'input_datetime.van_road_tax', icon: 'mdi:highway' }] },
      ],
    },
  });

  const chipsDevices = (cols) => ({
    type: 'custom:ccu-chips-card', grid_options: { columns: cols },
    entities: [
      { entity: 'binary_sensor.rain', name: 'Rain', icon: 'mdi:weather-rainy', hide_off: true },
      { entity: 'sensor.feels_like', name: 'Feels like', icon: 'mdi:thermometer-alert', show_state: true, alert_above: 32, hide_off: true },
      { entity: 'climate.living_ac', name: 'Living A/C', icon: 'mdi:air-conditioner', hide_off: true },
      { entity: 'climate.bedroom_ac', name: 'Bedroom A/C', icon: 'mdi:air-conditioner', hide_off: true },
      { entity: 'switch.air_cleaner', name: 'Air cleaner', icon: 'mdi:fan', hide_off: true },
      { entity: 'switch.pool_pump', name: 'Pool pump', icon: 'mdi:valve', hide_off: true },
      { entity: 'switch.uv_sterilizer', name: 'UV', icon: 'mdi:sun-wireless-outline', hide_off: true },
      { entity: 'light.pool', name: 'Pool light', icon: 'mdi:lightbulb', hide_off: true },
      { entity: 'sensor.washer_status', name: 'Washer', icon: 'mdi:washing-machine', hide_off: true, show_state: true, on_states: ['running', 'spinning', 'rinsing', 'drying'],
        text_map: { running: 'Wash', spinning: 'Spin', rinsing: 'Rinse', drying: 'Dry' }, secondary: { entity: 'sensor.washer_remaining' } },
    ],
    waste: { calendar: 'calendar.waste', next_days: 1, hide_today_after: '23:59', patterns: [
      { match: 'Waste: General', label: 'General', icon: 'mdi:trash-can', exact: true }, { match: 'Waste: Plastic', label: 'Plastic', icon: 'mdi:recycle', exact: true }] },
  });

  const header = () => ({
    type: 'custom:ccu-header-card', grid_options: { columns: 12 },
    header: { icon: 'home', values: [
      { entity: 'sensor.house_power', icon: 'bolt', color: 'accent', label: 'Load' },
      { entity: 'sensor.solar_power', icon: 'sun', color: 'on', label: 'Solar' },
      { entity: 'sensor.battery_soc', icon: 'battery', color: 'ok', label: 'Battery', runtime_load: 'sensor.load_power', runtime_capacity_kwh: 10, runtime_reserve_pct: 20, runtime_power: 'sensor.battery_power' },
    ], right: { entity: 'sensor.outdoor_temperature', label: 'outside' } },
  });

  const flow = () => ({
    type: 'custom:ccu-flow-card', grid_options: { columns: 12 },
    solar_today: 'sensor.solar_today', radiation: 'sensor.solar_radiation',
    solar: 'sensor.solar_power', grid: { entity: 'sensor.grid_power', invert: true }, battery: { entity: 'sensor.battery_power', soc: 'sensor.battery_soc' },
    consumers: [
      { entity: 'sensor.house_power', subtract: ['sensor.pool_power'], name: 'House', icon: 'mdi:home' },
      { entities: ['sensor.shed_a', 'sensor.shed_b', 'sensor.shed_c'], subtract: ['sensor.ev_power'], name: 'Shed', icon: 'mdi:warehouse' },
      { entity: 'sensor.pool_power', name: 'Pool', icon: 'mdi:pool' },
      { entity: 'sensor.ev_power', name: 'EV charger', icon: 'mdi:car-electric' },
    ],
    stats: [
      { entity: 'sensor.import_today', label: 'Import today', icon: 'mdi:transmission-tower' }, { entity: 'sensor.export_today', label: 'Export today', icon: 'mdi:flash' },
      { entity: 'sensor.import_month', label: 'Import month', icon: 'mdi:home' }, { entity: 'sensor.battery_charged_today', label: 'Charged today', icon: 'mdi:battery-charging' },
    ],
  });

  const battery = () => ({
    type: 'custom:ccu-battery-card', grid_options: { columns: 12 }, show_title: false,
    soc: 'sensor.battery_soc', capacity_kwh: 10, load: 'sensor.load_power', power: 'sensor.battery_power', grid_present: 'binary_sensor.grid_present', reserve_pct: 20, shutdown_pct: 10,
  });

  const room = (entity, name, icon, tempEntity, page) => ({ entity, name, icon, secondary: { entity: tempEntity }, tap_action: { action: 'navigate', navigation_path: nav(page) }, hold_action: 'toggle' });
  const rooms = (extra) => ({
    type: 'custom:ccu-buttons-card', grid_options: { columns: 12 }, columns: 2, columns_wide: 4,
    entities: [
      room('light.kitchen', 'Kitchen', 'mdi:pot-steam', 'sensor.kitchen_temperature', 'kitchen'), room('light.living_room', 'Living room', 'mdi:sofa', 'sensor.living_temperature', 'living-room'),
      room('light.ground_hall', 'Ground hall', 'mdi:stairs', 'sensor.ground_hall_temperature', 'ground-hall'), room('light.office', 'Office', 'mdi:flask', 'sensor.office_temperature', 'office'),
      room('light.ground_bath', 'Ground bath', 'mdi:toilet', 'sensor.ground_bath_temperature', 'ground-bath'), room('light.master_bedroom', 'Master bedroom', 'mdi:bed-double', 'sensor.master_bedroom_temperature', 'master-bedroom'),
      room('light.dressing', 'Dressing', 'mdi:bed-double', 'sensor.dressing_temperature', 'dressing'), room('light.guest_room', 'Guest room', 'mdi:bed-single', 'sensor.guest_room_temperature', 'guest-room'),
      room('light.upper_hall', 'Upper hall', 'mdi:stairs', 'sensor.upper_hall_temperature', 'upper-hall'), room('light.upper_bath', 'Upper bath', 'mdi:toilet', 'sensor.upper_bath_temperature', 'upper-bath'),
      room('light.pool', 'Pool', 'mdi:pool', 'sensor.pool_temperature', 'pool'), room('switch.shed_lights', 'Shed', 'mdi:warehouse', 'sensor.shed_temperature', 'shed'),
    ].concat(extra || []),
  });
  const gate = (cols) => ({ type: 'custom:ccu-buttons-card', columns: 1, grid_options: { columns: cols },
    entities: [{ entity: 'switch.gate', name: 'Gate', icon: 'mdi:gate', secondary: 'hold to open', tap_action: 'none', hold_action: 'toggle', on_as: 'alert' }] });
  const people = (layout, cols) => ({ type: 'custom:ccu-people-card', grid_options: { columns: cols }, ...(layout ? { layout } : {}), people: ['person.ana', 'person.maria', 'person.alex'] });
  const weather = () => ({
    type: 'custom:ccu-weather-card', grid_options: { columns: 12 }, weather: 'weather.home',
    sensors: { temperature: 'sensor.temp', feels_like: 'sensor.feels', humidity: 'sensor.hum', wind_speed: 'sensor.wind', wind_gust: 'sensor.gust', wind_direction: 'sensor.dir', rain_rate: 'sensor.rain_rate', rain_today: 'sensor.rain_today', rain_state: 'binary_sensor.raining', pressure: 'sensor.pressure', uv: 'sensor.uv', radiation: 'sensor.radiation' },
    tiles: ['humidity', 'wind', 'rain', 'pressure', 'uv', 'radiation'], days: 5,
  });
  const batteries = () => ({ type: 'custom:ccu-batteries-card', grid_options: { columns: 12 }, title: 'Device batteries',
    entities: [{ entity: 'sensor.tablet_battery', name: 'Wall tablet' }, { entity: 'sensor.phone_battery', name: 'Phone' }, { entity: 'sensor.car_battery', name: 'Car' }, { entity: 'sensor.remote_battery', name: 'TV remote' }] });
  const graph = () => ({ type: 'custom:ccu-graph-card', grid_options: { columns: 'full' }, title: 'Energy (last 6 h)', range: '6h', tabs: ['6h', '24h'], y_axis: 'right', height: 64, compact: true,
    series: [{ entity: 'sensor.house_power', name: 'Consumption', color: 'accent' }, { entity: 'sensor.solar_power', name: 'Solar', color: 'yellow', kind: 'line' }] });
  const dishwasher = () => ({ type: 'conditional', grid_options: { columns: 6 },
    conditions: [{ condition: 'numeric_state', entity: 'sensor.dishwasher_remaining', above: 0 }],
    card: { type: 'custom:ccu-buttons-card', columns: 1, entities: [{ entity: 'sensor.dishwasher_remaining', name: 'Dishwasher', icon: 'mdi:dishwasher', active: true, size: 'l' }] } });

  // the same bottom bar on every page: Home goes to the page of the device you hold (a long press jumps to the other one);
  // a phone shows 5 buttons, a tablet shows all 9
  const navbar = () => ({
    type: 'custom:ccu-nav-card', grid_options: { columns: 12 }, sticky: true,
    items: [
      { icon: 'home', label: 'Home', path_tablet: nav('tablet'), path_phone: nav('phone'), hold_path_phone: nav('tablet'), hold_path_tablet: nav('phone') },
      { icon: 'sun', label: 'Energy', path: nav('energy') },
      { icon: 'bolt', label: 'Solar', path: nav('solar') },
      { icon: 'bulb', label: 'Lights', path: nav('lights'), badge: ['sensor.lights_on'], badge_style: 'light' },
      { icon: 'camera', label: 'Cams', path: nav('cams'), badge: ['binary_sensor.cam1_person', 'binary_sensor.cam2_person'] },
      { icon: 'car', label: 'Car', path: nav('car'), device: 'tablet' },
      { icon: 'warehouse', label: 'Shed', path: nav('shed'), device: 'tablet' },
      { icon: 'pool', label: 'Pool', path: nav('pool'), device: 'tablet' },
      { icon: 'thermo', label: 'Status', path: nav('status'), device: 'tablet' },
    ],
  });

  const tablet = { title: 'Tablet', path: 'tablet', type: 'sections', max_columns: 2, sections: [
    { type: 'grid', column_span: 2, cards: [chipsStatus('full'), chipsDevices('full'), dishwasher(), graph()] },
    { type: 'grid', cards: [people('family', 12), weather(), batteries()] },
    { type: 'grid', cards: [flow(), battery(), rooms([gate(12).entities[0]])] },
    { type: 'grid', column_span: 2, cards: [navbar()] },
  ] };
  // on the phone Car and Status are buttons on the page (they are not in the bar)
  const phone = { title: 'Home', path: 'phone', type: 'sections', max_columns: 1, sections: [
    { type: 'grid', cards: [
      chipsDevices(12), header(), flow(), gate(6), chipsStatus(12), people(null, 6),
      rooms([
        { entity: 'sensor.car_battery', name: 'Car', icon: 'mdi:car', secondary: 'documents', tap_action: { action: 'navigate', navigation_path: nav('car') } },
        { entity: 'binary_sensor.grid_present', name: 'Status', icon: 'mdi:server', secondary: 'system', tap_action: { action: 'navigate', navigation_path: nav('status') } },
      ]),
      navbar(),
    ] },
  ] };

  window.CCU_DASHBOARD = { title: 'Calm Modern UI example', views: [tablet, phone] };
})();
